  'about.hero.h1':          { en: 'About<br><em>Engen Mauritius</em>', fr: 'À propos<br><em>d\'Engen Mauritius</em>' },

  'about.overview.label':   { en: 'Company Overview',    fr: 'Présentation de l\'entreprise' },
  'about.overview.h2':      { en: 'More Than <em>Just Fuel</em>', fr: 'Plus Que Du <em>Simple Carburant</em>' },
  'about.overview.p1':      { en: 'Engen Petroleum (Mauritius) Limited is a leading energy company in Mauritius, delivering high-quality fuels, lubricants, and convenience retail services across the island. Following its acquisition by Bhunjun Group through Beta Oil Terminal Ltd, the company is now fully Mauritian-owned.', fr: 'Engen Petroleum (Mauritius) Limited est une société énergétique de premier plan à Maurice, fournissant des carburants de haute qualité, des lubrifiants et des services de commerce de proximité à travers l\'île. Suite à son acquisition par le Groupe Bhunjun via Beta Oil Terminal Ltd, la société est désormais entièrement mauricienne.' },
  'about.overview.p2':      { en: 'Our stations are more than refuelling stops. They are part of the daily rhythm of Mauritian life — designed around real people and real needs: the family on a weekend drive, the worker stopping in before a long shift, the commuter who counts on us every morning. Fuel moves vehicles, but care moves people.', fr: 'Nos stations sont bien plus que de simples arrêts de ravitaillement. Elles font partie du rythme quotidien de la vie mauricienne — conçues autour de vraies personnes et de vrais besoins : la famille en promenade du week-end, le travailleur s\'arrêtant avant un long quart, le navetteur qui compte sur nous chaque matin. Le carburant fait avancer les voitures, mais c\'est l\'attention qui fait avancer les gens.' },
  'about.overview.commit.label': { en: 'Our Commitment', fr: 'Notre engagement' },
  'about.overview.commit.1': { en: 'Deliver reliable, high-quality energy solutions', fr: 'Fournir des solutions énergétiques fiables et de haute qualité' },
  'about.overview.commit.2': { en: 'Operate with integrity, safety, and responsibility', fr: 'Opérer avec intégrité, sécurité et responsabilité' },
  'about.overview.commit.3': { en: 'Support businesses, communities, and national development', fr: 'Soutenir les entreprises, les communautés et le développement national' },
