  'about.story.label':      { en: 'Our Story',           fr: 'Notre histoire' },
  'about.story.h2':         { en: 'Fuel Moves Vehicles. <em>Care Moves People.</em>', fr: 'Le carburant fait avancer les véhicules. <em>L\'attention fait avancer les gens.</em>' },
  'about.story.lead':       { en: 'Engen Mauritius was built on a belief that goes beyond fuel: that the way you are treated when you stop matters just as much as the quality of what goes in your tank.', fr: 'Engen Mauritius a été fondé sur une conviction qui va au-delà du carburant : la façon dont vous êtes traité lors de votre arrêt compte autant que la qualité de ce qui entre dans votre réservoir.' },
  'about.story.byline':     { en: 'Engen Mauritius — Brand Manifesto', fr: 'Engen Mauritius — Manifeste de marque' },
  'about.story.vision.h3':  { en: 'Our Vision',          fr: 'Notre vision' },
  'about.story.vision.p':   { en: 'To be the most trusted, human-centred fuel network in Mauritius — where every stop is a moment of care, quality, and belonging for every customer we serve.', fr: 'Être le réseau de carburant le plus digne de confiance et centré sur l\'humain à Maurice — où chaque arrêt est un moment d\'attention, de qualité et d\'appartenance pour chaque client que nous servons.' },
  'about.story.mission.h3': { en: 'Our Mission',         fr: 'Notre mission' },
  'about.story.mission.p':  { en: 'To deliver quality fuels, lubricants, and convenience retail through a safe, well-run network of stations — staffed by people who genuinely care about the customers and communities around them.', fr: 'Fournir des carburants de qualité, des lubrifiants et un commerce de proximité à travers un réseau de stations sûr et bien géré — animé par des personnes qui se soucient véritablement des clients et des communautés qui les entourent.' },

  'about.values.label':     { en: 'Our Values',          fr: 'Nos valeurs' },
  'about.values.h2':        { en: 'What We <em>Stand For</em>', fr: 'Ce en quoi <em>Nous croyons</em>' },
  'about.values.lead':      { en: 'Every decision, every station, every interaction — guided by five values that define who we are and how we operate across Mauritius.', fr: 'Chaque décision, chaque station, chaque interaction — guidées par cinq valeurs qui définissent qui nous sommes et comment nous opérons à Maurice.' },
  'about.values.v1.h3':     { en: 'Responsibility',      fr: 'Responsabilité' },
  'about.values.v1.p':      { en: 'We own our actions and their impact — on customers, communities, and the environment at every station in our network.', fr: 'Nous assumons nos actions et leur impact — sur les clients, les communautés et l\'environnement dans chaque station de notre réseau.' },
  'about.values.v2.h3':     { en: 'Care',                fr: 'Bienveillance' },
  'about.values.v2.p':      { en: 'Every person who stops at an Engen station matters. Genuine concern for customer well-being drives every interaction.', fr: 'Chaque personne qui s\'arrête dans une station Engen compte. La véritable préoccupation pour le bien-être des clients guide chaque interaction.' },
  'about.values.v3.h3':     { en: 'Integrity',           fr: 'Intégrité' },
  'about.values.v3.p':      { en: 'We operate with transparency — in how we fuel, how we price, and how we communicate with every customer and stakeholder.', fr: 'Nous opérons avec transparence — dans notre façon de ravitailler, de fixer les prix et de communiquer avec chaque client et partie prenante.' },
  'about.values.v4.h3':     { en: 'Respect',             fr: 'Respect' },
  'about.values.v4.p':      { en: 'Respect for our customers, our teams, and the communities where our stations operate is fundamental to how we work.', fr: 'Le respect de nos clients, de nos équipes et des communautés où nos stations opèrent est fondamental dans notre façon de travailler.' },
  'about.values.v5.h3':     { en: 'Belonging',           fr: 'Appartenance' },
  'about.values.v5.p':      { en: 'Engen stations are a pause point in Mauritian daily life — where every customer should feel welcome, valued, and at home.', fr: 'Les stations Engen sont un point de pause dans la vie quotidienne mauricienne — où chaque client devrait se sentir bienvenu, valorisé et chez lui.' },

  'about.hseq.label':       { en: 'Safety &amp; Sustainability', fr: 'Sécurité &amp; Durabilité' },
  'about.hseq.h2':          { en: 'HSEQ at the <em>Core</em>', fr: 'Le HSEQ au <em>Cœur</em>' },
  'about.hseq.p':           { en: 'Health, Safety, Environment, and Quality (HSEQ) are fundamental to how we operate. HSEQ is our licence to operate, guiding every decision and action across our business.', fr: 'La santé, la sécurité, l\'environnement et la qualité (HSEQ) sont fondamentaux dans notre façon d\'opérer. Le HSEQ est notre licence d\'exploitation, guidant chaque décision et action dans notre entreprise.' },
  'about.hseq.item1.strong':{ en: 'Health &amp; Safety', fr: 'Santé &amp; Sécurité' },
  'about.hseq.item2.strong':{ en: 'Environmental Commitment', fr: 'Engagement environnemental' },
  'about.hseq.item3.strong':{ en: 'Quality Assurance',  fr: 'Assurance qualité' },
  'about.hseq.item4.strong':{ en: 'Sustainability &amp; CSR', fr: 'Durabilité &amp; RSE' },

  'about.leadership.label': { en: 'Leadership &amp; Governance', fr: 'Direction &amp; Gouvernance' },
  'about.leadership.h2':    { en: 'The People &amp; Purpose <em>Behind Engen</em>', fr: 'Les Personnes &amp; la Mission <em>derrière Engen</em>' },

  'about.policies.label':   { en: 'Governance &amp; Policies', fr: 'Gouvernance &amp; Politiques' },
  'about.policies.h2':      { en: 'Operating with <em>Integrity</em>', fr: 'Opérer avec <em>Intégrité</em>' },
  'about.policies.p1.h3':   { en: 'HSEQ Policy',        fr: 'Politique HSEQ' },
  'about.policies.p2.h3':   { en: 'Code of Conduct &amp; Ethics', fr: 'Code de conduite &amp; d\'éthique' },
  'about.policies.p3.h3':   { en: 'Anti-Bribery &amp; Anti-Corruption', fr: 'Anti-corruption &amp; Intégrité' },
  'about.policies.p4.h3':   { en: 'Risk Management &amp; Internal Controls', fr: 'Gestion des risques &amp; Contrôles internes' },

  'about.cta.label':        { en: 'Visit Us',            fr: 'Visitez-nous' },
  'about.cta.h2':           { en: 'Find Your Nearest <em style="color:var(--yellow);font-style:normal;">Engen Station</em>', fr: 'Trouvez la <em style="color:var(--yellow);font-style:normal;">station Engen</em> la plus proche' },
  'about.cta.p':            { en: '37 stations across all nine districts of Mauritius — quality fuel, convenience, and real care at every stop.', fr: '37 stations dans les neuf districts de Maurice — carburant de qualité, commodité et véritable attention à chaque arrêt.' },
  'about.cta.btn1':         { en: 'Find a Station →',    fr: 'Trouver une station →' },
  'about.cta.btn2':         { en: 'Get in Touch',        fr: 'Prendre contact' },

