  'prod.fuels.h2':          { en: 'Powering Every <em>Journey</em>', fr: 'Alimentant chaque <em>Voyage</em>' },
  'prod.fuels.lead':        { en: 'At Engen Petroleum (Mauritius) Limited, we deliver a comprehensive range of high-quality fuels to power mobility, aviation, industrial activity, and maritime operations across the island.', fr: 'Chez Engen Petroleum (Mauritius) Limited, nous fournissons une gamme complète de carburants de haute qualité pour alimenter la mobilité, l\'aviation, l\'activité industrielle et les opérations maritimes à travers l\'île.' },
  'prod.fuels.mogas.cat':   { en: 'Retail Fuel',         fr: 'Carburant au détail' },
  'prod.fuels.mogas.h3':    { en: 'Mogas<br><small style="font-size:0.65em;opacity:0.6;">Unleaded Petrol</small>', fr: 'Mogas<br><small style="font-size:0.65em;opacity:0.6;">Essence sans plomb</small>' },
  'prod.fuels.mogas.p':     { en: 'Formulated for optimal engine performance, fuel efficiency, and reliability for everyday motorists.', fr: 'Formulé pour des performances moteur optimales, une efficacité énergétique et une fiabilité pour les automobilistes du quotidien.' },
  'prod.fuels.gasoil.cat':  { en: 'Retail / Commercial', fr: 'Détail / Commercial' },
  'prod.fuels.gasoil.h3':   { en: 'Gasoil<br><small style="font-size:0.65em;opacity:0.6;">Diesel</small>', fr: 'Gasoil<br><small style="font-size:0.65em;opacity:0.6;">Diesel</small>' },
  'prod.fuels.gasoil.p':    { en: 'Designed for performance and durability across transport fleets, logistics operators, industrial and agricultural users.', fr: 'Conçu pour la performance et la durabilité des flottes de transport, des opérateurs logistiques, des utilisateurs industriels et agricoles.' },
  'prod.fuels.jet.cat':     { en: 'Aviation',            fr: 'Aviation' },
  'prod.fuels.jet.h3':      { en: 'Jet A-1<br><small style="font-size:0.65em;opacity:0.6;">Aviation Fuel</small>', fr: 'Jet A-1<br><small style="font-size:0.65em;opacity:0.6;">Carburant d\'aviation</small>' },
  'prod.fuels.jet.p':       { en: 'Complies with DefStan 91-091 and EI 1530 specifications. Rigorous quality control and secure logistics ensure safety and operational continuity for every flight.', fr: 'Conforme aux spécifications DefStan 91-091 et EI 1530. Un contrôle qualité rigoureux et une logistique sécurisée garantissent la sécurité et la continuité opérationnelle pour chaque vol.' },
  'prod.fuels.marine.cat':  { en: 'Marine / Industrial', fr: 'Maritime / Industriel' },
  'prod.fuels.marine.h3':   { en: 'Marine<br><small style="font-size:0.65em;opacity:0.6;">HFO &amp; MGO</small>', fr: 'Marine<br><small style="font-size:0.65em;opacity:0.6;">HFO &amp; MGO</small>' },
  'prod.fuels.marine.p':    { en: 'Marine Fuel Oil (RMG 180) and Marine Gas Oil supplied in compliance with ISO 8217 standards. Dedicated bunkering facilities for reliable marine fueling operations.', fr: 'Huile combustible marine (RMG 180) et gazole marin conformes aux normes ISO 8217. Des installations de soutage dédiées pour des opérations d\'avitaillement marines fiables.' },
