  'con.h2.help':            { en: 'We\'re Here to <em style="color:var(--yellow);font-style:normal;">Help</em>', fr: 'Nous sommes là pour <em style="color:var(--yellow);font-style:normal;">vous aider</em>' },
  'con.desc':               { en: 'For any enquiries, please reach out to our team. Whether you are a customer, business partner, job applicant, or member of the media, we will ensure your query is directed to the right person and responded to promptly.', fr: 'Pour toute demande, veuillez contacter notre équipe. Que vous soyez client, partenaire commercial, candidat ou représentant des médias, nous veillerons à ce que votre demande soit dirigée vers la bonne personne et traitée rapidement.' },
